import{_ as o,a0 as p,w as s,s as n,I as r,x as e,a1 as i,A as a,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"提高调试能力的一些方法 | LCTT x X-CMD","titleTemplate":false,"description":"提高调试能力的一些方法 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"提高调试能力的一些方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"提高调试能力的一些方法 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220830 Some ways to get better at debugging","title":"提高调试能力的一些方法","tag":"202209","desc":""},"relativePath":"202209/20220830 Some ways to get better at debugging.md","filePath":"[post].md"}'),u={name:"202209/20220830 Some ways to get better at debugging.md"};function g(b,t,m,f,T,x){const l=p("Link");return s(),n("div",null,[t[26]||(t[26]=r("h1",{id:"提高调试能力的一些方法",tabindex:"-1"},[e("提高调试能力的一些方法 "),r("a",{class:"header-anchor",href:"#提高调试能力的一些方法","aria-label":"Permalink to “提高调试能力的一些方法”"},"​")],-1)),t[27]||(t[27]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202209/01/222854m78u44otl68yxbyu.jpg",alt:""})],-1)),r("p",null,[t[1]||(t[1]=e("你们好！我一直在编写一本关于调试的杂志（这是 ",-1)),i(l,{href:"https://twitter.com/b0rk/status/1562480240240525314?s=20&t=BwKd6i0mVCTaCud2HDEUBA"},{default:a(()=>[...t[0]||(t[0]=[e("目录的初稿",-1)])]),_:1}),t[2]||(t[2]=e("）。",-1))]),r("p",null,[t[4]||(t[4]=e("作为其中的一部分，我认为阅读一些关于调试的学术论文可能会很有趣，上周 ",-1)),i(l,{href:"https://third-bit.com/"},{default:a(()=>[...t[3]||(t[3]=[e("Greg Wilson",-1)])]),_:1}),t[5]||(t[5]=e(" 给我发了一些关于调试学术研究的论文。",-1))]),r("p",null,[t[8]||(t[8]=e("其中一篇论文（《",-1)),i(l,{href:"https://dl.acm.org/doi/abs/10.1145/3286960.3286970"},{default:a(()=>[...t[6]||(t[6]=[e("建立一个调试教学的框架[付费墙]",-1)])]),_:1}),t[9]||(t[9]=e("》）对我们有效调试所需的不同种类的知识/技能进行了分类，我非常喜欢。它来自另一篇关于故障排除的更一般性的论文：《",-1)),i(l,{href:"https://www.researchgate.net/profile/Woei-Hung/publication/225547853_Learning_to_Troubleshoot_A_New_Theory-Based_Design_Architecture/links/556f471c08aec226830a74e7/Learning-to-Troubleshoot-A-New-Theory-Based-Design-Architecture.pdf"},{default:a(()=>[...t[7]||(t[7]=[e("学会排错：一个新的基于理论的设计架构",-1)])]),_:1}),t[10]||(t[10]=e("》。",-1))]),t[28]||(t[28]=d('<p>我认为这个分类对于思考如何更好地进行调试是一个非常有用的结构，所以我把论文中的五个类别重新规划为你可以采取的行动，以提高调试的效率。</p><p>以下是这些行动：</p><h4 id="_1、学习代码库" tabindex="-1">1、学习代码库 <a class="header-anchor" href="#_1、学习代码库" aria-label="Permalink to “1、学习代码库”">​</a></h4><p>要调试一些代码，你需要了解你正在使用的代码库。</p><p>这似乎有点显而易见（当然，不了解代码的工作原理，你就无法调试代码！）</p><p>这种学习随着时间的推移会很自然地发生，而且实际上调试也是 <em>学习</em> 一个新的代码库如何工作的最好方法之一—— 看到一些代码是如何崩溃的，有助于你了解它是如何工作的。</p><p>该论文将此称为“系统知识”。</p><h4 id="_2、学习系统" tabindex="-1">2、学习系统 <a class="header-anchor" href="#_2、学习系统" aria-label="Permalink to “2、学习系统”">​</a></h4><p>论文中提到，你需要了解编程语言，但我认为不止于此 —— 为了修复 bug，往往你需要学习很多更广泛的环境，而不仅仅是语言。</p><p>举个例子，如果你是后端 Web 开发者，你可能需要的一些“系统”知识包括：</p><ul><li>HTTP 缓存如何工作</li><li>CORS</li><li>数据库事务是如何工作的</li></ul><p>我发现我经常需要更有意识地去学习像这样的系统性的东西 —— 我需要真正花时间去查找和阅读它们。</p><p>该论文将此称为“领域知识”。</p><h4 id="_3、学习你的工具" tabindex="-1">3、学习你的工具 <a class="header-anchor" href="#_3、学习你的工具" aria-label="Permalink to “3、学习你的工具”">​</a></h4><p>现在有很多工具，例如：</p><ul><li>调试器（GDB 等）</li><li>浏览器开发工具</li><li><ruby>剖析器<rt>profiler</rt></ruby></li><li><code>strace</code> / <code>ltrace</code></li><li><code>tcpdump</code> / <code>wireshark</code></li><li>核心转储</li><li>甚至像错误信息这样的基本东西（如何正确阅读它们）</li></ul><p>我在这个博客上写了很多关于调试工具的文章，并且肯定学习这些工具给我带来了巨大的变化。</p><p>该论文将此称为“处理性知识”。</p><h4 id="_4、学习策略" tabindex="-1">4、学习策略 <a class="header-anchor" href="#_4、学习策略" aria-label="Permalink to “4、学习策略”">​</a></h4><p>这是最模糊的一类，在如何高效调试的过程中，我们都有很多策略和启发式方法。比如说：</p><ul><li>写一个单元测试</li><li>写一个小的独立程序来重现这个错误</li><li>找到一个能工作的版本的代码，看看有什么变化</li><li>打印出无数的东西</li><li>增加额外的日志记录</li><li>休息一下</li><li>向朋友解释这个错误，然后在中途发现问题所在</li><li>查看 GitHub 上的问题，看看是否有匹配的问题</li></ul><p>在写这本杂志的时候，我一直在思考这个类别，但我想让这篇文章简短，所以我不会在这里多说。</p><p>该论文将此称为“战略知识”。</p><h4 id="_5、获得经验" tabindex="-1">5、获得经验 <a class="header-anchor" href="#_5、获得经验" aria-label="Permalink to “5、获得经验”">​</a></h4><p>最后一个类别是“经验”。这篇论文对此有一个非常有趣的评论：</p><blockquote><p>他们的研究结果并没有显示出新手和专家所采用的策略有什么明显的区别。专家只是形成了更多正确的假设，并且在寻找故障方面更有效率。作者怀疑这个结果是由于新手和专家之间的编程经验不同造成的。</p></blockquote><p>这真的引起了我的共鸣 —— 我遇到过很多第一次遇到时非常令人沮丧和困难的 bug，而在第五次、第十次或第二十次时就非常简单了。</p><p>对我来说，这也是最直接的知识类别之一 —— 你需要做的就是调查一百万个 bug，反正这就是我们作为程序员的全部生活 : ) 。这需要很长的时间，但我觉得它发生得很自然。</p><p>本文将此称为“经验知识”。</p><h4 id="就这样吧" tabindex="-1">就这样吧！ <a class="header-anchor" href="#就这样吧" aria-label="Permalink to “就这样吧！”">​</a></h4><p>我打算把这篇文章写得很短，我只是非常喜欢这个分类，想把它分享出来。</p><hr>',32)),r("p",null,[t[12]||(t[12]=e("via: ",-1)),i(l,{href:"https://jvns.ca/blog/2022/08/30/a-way-to-categorize-debugging-skills/"},{default:a(()=>[...t[11]||(t[11]=[e("https://jvns.ca/blog/2022/08/30/a-way-to-categorize-debugging-skills/",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=e("作者：",-1)),i(l,{href:"https://jvns.ca/"},{default:a(()=>[...t[13]||(t[13]=[e("Julia Evans",-1)])]),_:1}),t[18]||(t[18]=e(" 选题：",-1)),i(l,{href:"https://github.com/lkxed"},{default:a(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),i(l,{href:"https://github.com/aftermath0703"},{default:a(()=>[...t[15]||(t[15]=[e("aftermath0703",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),i(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),i(l,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const w=o(u,[["render",g]]);export{C as __pageData,w as default};
